import { buildBudgetMs, cmdBudgetMs, orchestratorBudgetMs, daemonBudgetMs } from "../../../../../🔨️modules/🏃️process/⏱️budget/🟦️.ts";
import { terminateOwnedProcessTree } from "../../../../../🔨️modules/🏃️process/🪓️termination/🟦️.ts";

/** 🏃️ Process execution with opt-in wall-clock budgets for repository commands and builds,
 * the `spawnSync` runners built on them, workspace-aware `.bin`
 * resolution and the dev/ship build-mode switch. Split out of `📦️packages/🟦️typescript/🟦️.ts` so a
 * consumer that only spawns a tool (the plugin package's jco/wasm-opt steps, and through them the
 * extension store and `⚙️vite.config.ts`) never drags the repository library's `🔍️discovery` taxonomy
 * walk into its module graph. */
import { spawn, spawnSync } from "node:child_process";
import { existsSync, readFileSync } from "node:fs";
import { dirname, join, relative, resolve, isAbsolute } from "node:path";
import { fileURLToPath } from "node:url";
import { prepareCargoWorkspaceInvocation } from "../🗂️workspaces/🦀️cargo/🟦️.ts";
import { getWorkspaceRoot } from "../🗂️workspaces/🟦️.ts";
import { devToolingEnv } from "./🌿️environment/🟦️.ts";

/** 🧭️Selects the opt-in build budget for Cargo and command budget for other executables; both default to unlimited. */
export function defaultBudgetMs(cmd: string): number {
  return cmd === "cargo" ? buildBudgetMs() : cmdBudgetMs();
}

/** ⏱️Timeout hint for a budget-exceeded message; `cargo` commands default to the shared target-dir lock-contention hint (by far the most common real cause), everything else to a generic budget-tuning hint. An explicit `override` always wins. */
export function budgetTimeoutHint(cmd: string, override?: string): string {
  if (override) return override;
  return cmd === "cargo"
    ? "Likely shared cargo target-dir lock contention from another concurrent session — investigate before retrying."
    : "Trim it, or raise its budget (`budgetMs`, `SEMIO_CMD_BUDGET_MS`, `SEMIO_BUILD_BUDGET_MS`).";
}

export interface RunCmdOpts {
  cwd?: string;
  env?: NodeJS.ProcessEnv;
  /** ⏱️Wall-clock budget (ms); zero disables the timeout. Defaults to [[defaultBudgetMs]]. Named wrappers use [[orchestratorBudgetOpts]] / [[daemonBudgetOpts]]. */
  budgetMs?: number;
  onTimeoutHint?: string;
  /** 🐚️ Resolve the command through the platform shell — required on native Windows for `.cmd`/`.bat` launchers such as `bunx`. */
  shell?: boolean;
}

/** ⏱️[[RunCmdOpts]] preset for nx/script orchestrators — [[orchestratorBudgetMs]] and full CPU [[devToolingEnv]]. */
export function orchestratorBudgetOpts(extra: Partial<NodeJS.ProcessEnv> = {}): RunCmdOpts {
  return { budgetMs: orchestratorBudgetMs(), env: devToolingEnv(extra) };
}

/** ⏱️[[RunCmdOpts]] preset for dev servers and long-lived daemons — [[daemonBudgetMs]] and [[devToolingEnv]]. */
export function daemonBudgetOpts(extra: Partial<NodeJS.ProcessEnv> = {}): RunCmdOpts {
  return { budgetMs: daemonBudgetMs(), env: devToolingEnv(extra) };
}

/** 🌊️ The library's cargo relay, `⚡️caching/🦀️cargo/📜️script.ts relay <cargo args…>` ([[cargoStreamingStatus]]). */
export const CARGO_RELAY_SCRIPT = join(dirname(fileURLToPath(import.meta.url)), "..", "⚡️caching", "🦀️cargo", "📜️script.ts");

/** 🌊️ Carries a relayed cargo's wall-clock budget (ms, `0` = unlimited) from [[runCmd]] into the relay. */
export const CARGO_RELAY_BUDGET_ENV = "SEMIO_CARGO_RELAY_BUDGET_MS";

/** 🌊️ Runs `cargo` with its stdout/stderr piped and forwarded, never inherited: Bun marks its own stdio `O_NONBLOCK` once
 * written and an inherited pipe shares that flag, so a cargo burst (the replayed warnings of fresh units) fails with
 * `EAGAIN` — output cut mid-line, exit 101 — as soon as a slow reader lets the 64 KiB pipe fill (ticket 26/09/23 W4: flaky
 * component builds, the trusted-catalog publish's `os-hub` build). Bun's own writer waits the pipe out. Returns cargo's exit
 * status; `budgetMs` (> 0) elapsing or a SIGINT/SIGTERM of this process ends the whole cargo tree and throws. */
export async function cargoStreamingStatus(args: readonly string[], cwd: string, env: NodeJS.ProcessEnv, budgetMs: number): Promise<number> {
  prepareCargoWorkspaceInvocation(getWorkspaceRoot(), args, cwd);
  const child = spawn("cargo", [...args], { cwd, env, stdio: ["inherit", "pipe", "pipe"], detached: process.platform !== "win32" });
  child.stdout!.pipe(process.stdout, { end: false });
  child.stderr!.pipe(process.stderr, { end: false });
  let stopped: string | undefined;
  const stop = (reason: string): void => {
    stopped ??= reason;
    if (child.exitCode === null && child.signalCode === null && child.pid) terminateOwnedProcessTree(child.pid);
  };
  const onSignal = (signal: NodeJS.Signals): void => stop(`stopped: the relay received ${signal}`);
  const budget = budgetMs > 0 ? setTimeout(() => {
    console.error(`[budget] cargo ${args.join(" ")} exceeded ${budgetMs}ms — killed. ${budgetTimeoutHint("cargo")}`);
    stop(`exceeded ${budgetMs}ms`);
  }, budgetMs) : undefined;
  process.once("SIGINT", onSignal);
  process.once("SIGTERM", onSignal);
  try {
    const [code, signal] = await new Promise<[number | null, NodeJS.Signals | null]>((accept, reject) => {
      child.once("error", reject);
      child.once("close", (exitCode, exitSignal) => accept([exitCode, exitSignal]));
    });
    if (stopped || signal) throw new Error(`cargo ${args.join(" ")} ${stopped ?? `killed by signal ${signal}`}`);
    return code ?? 1;
  } finally {
    if (budget) clearTimeout(budget);
    process.removeListener("SIGINT", onSignal);
    process.removeListener("SIGTERM", onSignal);
  }
}

/** ⏱️Shared `spawnSync` core for [[runCmd]]/[[runCmdStatus]]: throws on spawn error, budget timeout, or signal kill (printing `[budget]` first on timeout); otherwise returns the exit status. `cargo` runs through
 * [[CARGO_RELAY_SCRIPT]] (POSIX), so it never writes to an inherited, possibly non-blocking descriptor ([[cargoStreamingStatus]]). */
function runCmdInternal(cmd: string, args: string[], opts: RunCmdOpts): number {
  if (cmd === "cargo") prepareCargoWorkspaceInvocation(getWorkspaceRoot(), args, opts.cwd ?? process.cwd());
  const budgetMs = opts.budgetMs ?? defaultBudgetMs(cmd);
  const formattedArgs = [...args];
  if (cmd === "bun" || cmd === process.execPath) {
    if (formattedArgs[0] && !formattedArgs[0].startsWith("-") && !formattedArgs[0].includes("/") && !formattedArgs[0].includes("\\") && !workspaceScriptExists(formattedArgs[0])) {
      const resolved = resolveWorkspaceBin(formattedArgs[0], opts.cwd ?? process.cwd());
      if (resolved) {
        formattedArgs[0] = resolved;
      }
    }
  }
  const relayed = cmd === "cargo" && process.platform !== "win32";
  const result = relayed
    ? spawnSync(process.versions.bun ? process.execPath : "bun", [CARGO_RELAY_SCRIPT, "relay", ...formattedArgs], {
        stdio: "inherit",
        cwd: opts.cwd,
        env: { ...(opts.env ?? process.env), [CARGO_RELAY_BUDGET_ENV]: String(budgetMs) },
        timeout: budgetMs > 0 ? budgetMs + 60_000 : 0,
        killSignal: "SIGTERM",
        shell: false,
      })
    : spawnSync(cmd, formattedArgs, {
        stdio: "inherit",
        cwd: opts.cwd,
        env: opts.env ?? process.env,
        timeout: budgetMs,
        killSignal: "SIGKILL",
        shell: opts.shell ?? false,
      });
  if (result.error) {
    if ((result.error as NodeJS.ErrnoException).code === "ETIMEDOUT") {
      console.error(`[budget] ${cmd} ${args.join(" ")} exceeded ${budgetMs}ms — killed. ${budgetTimeoutHint(cmd, opts.onTimeoutHint)}`);
    }
    throw result.error;
  }
  if (result.signal) throw new Error(`${cmd} ${args.join(" ")} killed by signal ${result.signal}`);
  return result.status ?? 1;
}

/**
 * 🏃️Runs a subprocess with inherited stdio and an opt-in wall-clock budget (default [[defaultBudgetMs]]);
 * throws on non-zero exit, signal, or budget exceed (the `[budget]` line is printed
 * to stderr first so it survives a caller's try/catch, e.g. [[tryRun]]).
 */
export function runCmd(cmd: string, args: string[], opts: RunCmdOpts = {}): void {
  const status = runCmdInternal(cmd, args, opts);
  if (status !== 0) throw new Error(`${cmd} ${args.join(" ")} exited with status ${status}`);
}

/** 🏃️Like [[runCmd]] but returns the exit status instead of throwing on non-zero exit — for call sites
 *  that branch on it. Budget exceed still prints `[budget]` and throws (never silently returns a status). */
export function runCmdStatus(cmd: string, args: string[], opts: RunCmdOpts = {}): number {
  return runCmdInternal(cmd, args, opts);
}

/** 🏃️Like [[runCmd]] but ignores failures, including timeouts from an explicitly configured budget. */
export function tryRun(cmd: string, args: string[], opts: RunCmdOpts = {}): void {
  try {
    runCmd(cmd, args, opts);
  } catch {
    /* optional */
  }
}

/** 🔍️ Resolves a Node tool from installation launchers or its package bin declaration in the caller and workspace scopes. */
export function resolveWorkspaceBin(binName: string, cwd: string = process.cwd()): string | null {
  const shortName = binName.includes("/") ? binName.split("/").pop()! : binName;
  for (const root of new Set([cwd, getWorkspaceRoot()])) {
    const launcher = join(root, "node_modules", ".bin", shortName);
    if (existsSync(launcher)) return launcher;
    const owner = join(root, "node_modules", binName), manifest = join(owner, "package.json");
    if (!existsSync(manifest)) continue;
    const { bin } = JSON.parse(readFileSync(manifest, "utf8")) as { bin?: string | Record<string, string> };
    const entry = typeof bin === "string" ? bin : bin?.[shortName];
    if (typeof entry !== "string") continue;
    const executable = resolve(owner, entry), path = relative(owner, executable).replaceAll("\\", "/");
    if (!isAbsolute(path) && path !== ".." && !path.startsWith("../") && existsSync(executable)) return executable;
  }
  return null;
}

let workspaceScriptNames: ReadonlySet<string> | null = null;

/** 📜️Whether the workspace `package.json` declares a script under `name`. A declared script is the
 * workspace's deliberate wrapper for that tool (`nx` routes through the caching bootstrap, which
 * owns the daemon-served project graph the async ES-module inference plugin needs), so `bun <name>`
 * must reach the script and never the bare `node_modules/.bin` entry of the same name. */
export function workspaceScriptExists(name: string): boolean {
  if (workspaceScriptNames === null) {
    const manifest = join(getWorkspaceRoot(), "package.json");
    const scripts = existsSync(manifest) ? (JSON.parse(readFileSync(manifest, "utf8")) as { scripts?: Record<string, string> }).scripts ?? {} : {};
    workspaceScriptNames = new Set(Object.keys(scripts));
  }
  return workspaceScriptNames.has(name);
}

/** 🟢️Runs a CLI tool using `node` synchronously in `cwd`, returning status code. */
export function runNodeBinStatus(args: string[], cwd: string = process.cwd(), env: NodeJS.ProcessEnv = process.env): number {
  const binName = args[0]!;
  const resolved = resolveWorkspaceBin(binName, cwd);
  const executable = resolved ?? binName;
  const result = spawnSync("node", [executable, ...args.slice(1)], { cwd, env, shell: false, stdio: "inherit" });
  if (result.error) {
    console.error(result.error);
    return 1;
  }
  return result.status ?? 1;
}

/** 🟢️Runs a CLI tool using `node` synchronously in `cwd`. */
export function runNodeBin(args: string[], cwd: string = process.cwd(), env: NodeJS.ProcessEnv = process.env): void {
  const status = runNodeBinStatus(args, cwd, env);
  if (status !== 0) process.exit(status);
}

/** 🚦️ Whether child builds should use fast dev artifacts or ship optimization. */
export type SemioBuildMode = "dev" | "ship";

/** 🚦️ `ship` only when `SEMIO_BUILD_MODE=ship`; default is dev for local/agent loops. */
export function semioBuildMode(): SemioBuildMode {
  return process.env.SEMIO_BUILD_MODE === "ship" ? "ship" : "dev";
}

/** 🚀️ Env for nx/build orchestrators so spawned crate `wasm` scripts inherit ship mode. */
export function semioShipEnv(): NodeJS.ProcessEnv {
  return { ...process.env, SEMIO_BUILD_MODE: "ship" };
}

/** 📂 Cargo output directory name for a profile (`dev` → `debug`). */
export function cargoProfileDir(profile: string): string {
  return profile === "dev" ? "debug" : profile;
}

import { buildBudgetMs } from "../../../../../../🔨️modules/🏃️process/⏱️budget/🟦️.ts";
import { prepareCargoWorkspaceInvocation } from "../../🗂️workspaces/🦀️cargo/🟦️.ts";
import { getWorkspaceRoot } from "../../🗂️workspaces/🟦️.ts";

import { runOwnedCommand } from "../../../../../../🔨️modules/🏃️process/🎛️owned-execution/🟦️.ts";

/** 🦀️ Executes caller commands under the repository's authored Cargo and build-budget policy. */
export async function runRepositoryCommand(command: string, args: string[], cwd: string, label: string, timeoutMs = buildBudgetMs(), options: { stdout?: "inherit" | "ignore"; env?: Readonly<Record<string, string | undefined>>; signal?: AbortSignal; onLine?: (line: string) => void } = {}): Promise<void> {
  if (options.signal?.aborted) throw new Error(`${label} stopped: cancelled`);
  if (command === "cargo") prepareCargoWorkspaceInvocation(getWorkspaceRoot(), args, cwd);
  return runOwnedCommand(command, args, cwd, label, timeoutMs, options);
}

import { cargoRepositoryPackages, cargoWorkspaceForManifest } from "../../../🗂️workspaces/🦀️cargo/🟦️.ts";
import { readFileSync } from "node:fs";
import { dirname, isAbsolute, join, relative, resolve } from "node:path";

export type CargoDirectionDependency = Readonly<{ name: string; alias: string; owner: string | null; kind: "normal" | "dev" | "build"; optional: boolean; platform: string | null }>;
export type CargoDirectionPackage = Readonly<{ name: string; owner: string; role: string | null; dependencies: readonly CargoDirectionDependency[] }>;
export type CargoDirectionPolicy = Readonly<{ areaLayers: Readonly<Record<string, "framework" | "implementation" | "repo-wide">>; roles: readonly string[]; ownerRoles: readonly Readonly<{ path: string; roles: readonly string[] }>[]; rules: Readonly<Record<string, Readonly<{ fromRoles: readonly string[]; toRoles: readonly string[]; fromOwnerPaths?: readonly string[]; toOwnerSegments?: readonly string[] }>>> }>;
export type CargoDirectionViolation = Readonly<{ rule: string; from: string; to: string; alias: string; kind: CargoDirectionDependency["kind"]; optional: boolean; platform: string | null }>;
export type CargoDirectionProblem = Readonly<{ code: "missing-role" | "unknown-role" | "unclassified-owner" | "owner-role-mismatch" | "unclassified-role-owner"; owner: string }>;
export type CargoDirectionReport = Readonly<{ packages: number; localDependencies: number; violations: readonly CargoDirectionViolation[]; problems: readonly CargoDirectionProblem[] }>;

const object = (value: unknown): Record<string, any> => {
  if (!value || typeof value !== "object" || Array.isArray(value)) throw new Error("Cargo direction requires readable object metadata");
  return value as Record<string, any>;
};
const text = (value: unknown): string => {
  if (typeof value !== "string" || !value) throw new Error("Cargo direction requires a nonempty name or owner path");
  return value;
};
const array = (value: unknown): unknown[] => {
  if (!Array.isArray(value)) throw new Error("Cargo direction requires complete array metadata");
  return value;
};
const ownerPath = (root: string, path: string): string => {
  const owner = relative(root, path).replaceAll("\\", "/");
  if (!owner || owner.startsWith("..") || isAbsolute(owner)) throw new Error(`Cargo direction owner escapes the authored workspace: ${path}`);
  return owner;
};
const role = (manifest: Record<string, any>): string | null => manifest.package?.metadata?.semio?.role ?? null;

/** 🧾️ Inventories all authored Cargo members and declaration kinds independently of the Cargo graph. */
export function cargoDirectionInventory(root: string): readonly CargoDirectionPackage[] {
  const read = (path: string): Record<string, any> => object(Bun.TOML.parse(readFileSync(path, "utf8")));
  const members = cargoRepositoryPackages(root).map(member => member.directory);
  const found: CargoDirectionPackage[] = [], pending = [...members], visited = new Set<string>();
  for (let index = 0; index < pending.length; index++) {
    const member = pending[index]!;
    const owner = ownerPath(root, resolve(root, member));
    if (visited.has(owner)) continue;
    visited.add(owner);
    const manifest = read(join(root, owner, "Cargo.toml"));
    const authority = cargoWorkspaceForManifest(root, `${owner}/Cargo.toml`);
    const workspace = object(read(join(root, authority.manifest)).workspace);
    const workspaceRoot = resolve(root, authority.directory);
    const dependencies: CargoDirectionDependency[] = [];
    const collect = (tables: Record<string, any>, platform: string | null): void => {
      for (const [table, kind] of [["dependencies", "normal"], ["dev-dependencies", "dev"], ["build-dependencies", "build"]] as const) {
        for (const [alias, declaration] of Object.entries(tables[table] ?? {})) {
          const local = typeof declaration === "string" ? { version: declaration } : object(declaration);
          const inherited = local.workspace === true;
          const source = inherited ? object(workspace.dependencies ?? {})[alias] : local;
          if (inherited && source === undefined) throw new Error(`Cargo direction cannot read inherited dependency: ${owner} → ${alias}`);
          const base = typeof source === "string" ? { version: source } : object(source);
          const value = { ...base, ...local };
          if (value.optional !== undefined && typeof value.optional !== "boolean") throw new Error(`Cargo direction requires a boolean optional declaration: ${owner} → ${alias}`);
          dependencies.push({ name: text(value.package ?? alias), alias, owner: value.path === undefined ? null : ownerPath(root, resolve(inherited ? workspaceRoot : join(root, owner), text(value.path))), kind, optional: value.optional ?? false, platform });
        }
      }
    };
    collect(manifest, null);
    for (const [platform, tables] of Object.entries(manifest.target ?? {})) collect(object(tables), platform);
    found.push({ name: text(object(manifest.package).name), owner, role: role(manifest), dependencies });
    for (const dep of dependencies) if (dep.owner !== null && !visited.has(dep.owner)) pending.push(dep.owner);
  }
  return found;
}

/** 🦀️ Adapts Cargo's declared metadata behind a repository-owned language-neutral contract. */
export function cargoDirectionMetadata(value: unknown, root: string): readonly CargoDirectionPackage[] {
  if (Array.isArray(value)) {
    const rows = value.flatMap(entry => cargoDirectionMetadata(entry, root));
    if (!rows.length || new Set(rows.map(row => row.owner)).size !== rows.length || new Set(rows.map(row => row.name)).size !== rows.length) throw new Error("Cargo direction repeats workspace contribution identities");
    return rows;
  }
  const metadata = object(value), packages = array(metadata.packages), members = array(metadata.workspace_members).map(text);
  const selectedRoot = relative(root, resolve(text(metadata.workspace_root)));
  if (selectedRoot.startsWith("..") || isAbsolute(selectedRoot)) throw new Error("Cargo direction metadata belongs to a different repository");
  if (metadata.version !== 1 || !packages.length || members.length !== packages.length || new Set(members).size !== members.length) throw new Error("Cargo direction metadata is empty or incomplete");
  const ids = packages.map((value) => text(object(value).id));
  if (new Set(ids).size !== ids.length || JSON.stringify([...ids].sort()) !== JSON.stringify([...members].sort())) throw new Error("Cargo direction metadata omits authored workspace members");
  return packages.map((value) => {
    const pkg = object(value), owner = ownerPath(root, dirname(text(pkg.manifest_path)));
    return { name: text(pkg.name), owner, role: pkg.metadata?.semio?.role ?? null, dependencies: array(pkg.dependencies).map((value) => {
      const dep = object(value), kind = dep.kind === null ? "normal" : dep.kind;
      if (kind !== "normal" && kind !== "dev" && kind !== "build") throw new Error("Cargo direction metadata has an unknown dependency kind");
      if (typeof dep.optional !== "boolean" || (dep.target !== null && typeof dep.target !== "string")) throw new Error("Cargo direction metadata omits dependency activation declarations");
      return { name: text(dep.name), alias: text(dep.rename ?? dep.name), owner: dep.path === undefined || dep.path === null ? null : ownerPath(root, text(dep.path)), kind, optional: dep.optional, platform: dep.target };
    }) };
  });
}

/** 🧱️ Enforces physical and semantic direction for every local declaration without role omissions or exceptions. */
export function cargoDependencyDirectionReport(graph: readonly CargoDirectionPackage[], inventory: readonly CargoDirectionPackage[], policy: CargoDirectionPolicy): CargoDirectionReport {
  const validate = (packages: readonly CargoDirectionPackage[]): void => {
    if (!Array.isArray(packages) || !packages.length) throw new Error("Cargo direction requires a complete authored package inventory");
    if (new Set(packages.map((pkg) => pkg.owner)).size !== packages.length || new Set(packages.map((pkg) => pkg.name)).size !== packages.length) throw new Error("Cargo direction repeats a package owner or name");
    for (const pkg of packages) {
      text(pkg.name); text(pkg.owner);
      if (pkg.role !== null && typeof pkg.role !== "string") throw new Error("Cargo direction requires readable semantic role metadata");
      for (const value of array(pkg.dependencies)) {
        const dep = object(value);
        text(dep.name); text(dep.alias);
        if (!["normal", "dev", "build"].includes(dep.kind) || typeof dep.optional !== "boolean" || (dep.platform !== null && typeof dep.platform !== "string")) throw new Error("Cargo direction requires complete declaration activation metadata");
        if (dep.owner !== null) {
          const target = packages.find((pkg) => pkg.owner === text(dep.owner));
          if (!target || target.name !== dep.name) throw new Error(`Cargo direction omits a declared local target: ${pkg.owner} → ${dep.owner}`);
        }
      }
    }
  };
  validate(graph); validate(inventory);
  const signature = (packages: readonly CargoDirectionPackage[]): string => JSON.stringify(packages.map((pkg) => [pkg.name, pkg.owner, pkg.role, pkg.dependencies.map((dep) => [dep.name, dep.alias, dep.owner, dep.kind, dep.optional, dep.platform]).sort()]).sort());
  if (signature(graph) !== signature(inventory)) throw new Error("Cargo direction metadata disagrees with the independently inventoried authored declarations");
  const areas = Object.entries(object(policy.areaLayers)).sort(([a], [b]) => b.length - a.length);
  if (!areas.length || areas.some(([, layer]) => !["framework", "implementation", "repo-wide"].includes(layer)) || !Array.isArray(policy.roles) || !policy.roles.length || new Set(policy.roles).size !== policy.roles.length) throw new Error("Cargo direction requires declared physical areas and semantic roles");
  const layer = (owner: string): string | undefined => areas.find(([area]) => owner === area || owner.startsWith(`${area}/`))?.[1];
  if (!Array.isArray(policy.ownerRoles) || !policy.ownerRoles.length || new Set(policy.ownerRoles.map((rule) => rule.path)).size !== policy.ownerRoles.length || policy.ownerRoles.some((rule) => !rule || typeof rule.path !== "string" || !rule.path || !Array.isArray(rule.roles) || !rule.roles.length || new Set(rule.roles).size !== rule.roles.length || rule.roles.some((role: string) => !policy.roles.includes(role)))) throw new Error("Cargo direction requires complete distinct owner role classifications");
  const owners = policy.ownerRoles.map((rule) => ({ pattern: new RegExp(rule.path, "u"), roles: rule.roles }));
  const rules = Object.entries(object(policy.rules));
  if (!rules.length || rules.some(([name, rule]) => !name || Object.keys(object(rule)).some(key => !["fromRoles", "toRoles", "fromOwnerPaths", "toOwnerSegments"].includes(key)))) throw new Error("Cargo direction requires closed named rules");
  if (rules.some(([, rule]) => [rule.fromRoles, rule.toRoles].some(roles => !Array.isArray(roles) || new Set(roles).size !== roles.length || roles.some((role: unknown) => typeof role !== "string" || !policy.roles.includes(role))))) throw new Error("Cargo direction policy requires distinct known semantic roles");
  if (rules.some(([, rule]) => (!rule.fromRoles.length && !rule.fromOwnerPaths?.length) || (!rule.toRoles.length && !rule.toOwnerSegments?.length))) throw new Error("Cargo direction requires nonempty source and target selectors");
  if (rules.some(([, rule]) => rule.toOwnerSegments !== undefined && (!Array.isArray(rule.toOwnerSegments) || !rule.toOwnerSegments.length || new Set(rule.toOwnerSegments).size !== rule.toOwnerSegments.length || rule.toOwnerSegments.some((segment: unknown) => typeof segment !== "string" || !segment || /[/\\]/u.test(segment) || segment === "." || segment === "..")))) throw new Error("Cargo direction policy requires exact owner segments");
  if (rules.some(([, rule]) => rule.fromOwnerPaths !== undefined && (!Array.isArray(rule.fromOwnerPaths) || !rule.fromOwnerPaths.length || new Set(rule.fromOwnerPaths).size !== rule.fromOwnerPaths.length || rule.fromOwnerPaths.some((path: unknown) => typeof path !== "string" || !path)))) throw new Error("Cargo direction policy requires distinct source owner patterns");
  const sourceOwners = new Map<string, readonly RegExp[]>(rules.map(([name, rule]) => [name, (rule.fromOwnerPaths ?? []).map((pattern: string) => new RegExp(pattern, "u"))]));
  const problems: CargoDirectionProblem[] = [], violations: CargoDirectionViolation[] = [];
  let localDependencies = 0;
  for (const pkg of graph) {
    if (!layer(pkg.owner)) problems.push({ code: "unclassified-owner", owner: pkg.owner });
    if (!pkg.role) problems.push({ code: "missing-role", owner: pkg.owner });
    else if (!policy.roles.includes(pkg.role)) problems.push({ code: "unknown-role", owner: pkg.owner });
    const owner = owners.find((rule) => rule.pattern.test(pkg.owner));
    if (!owner) problems.push({ code: "unclassified-role-owner", owner: pkg.owner });
    else if (pkg.role && policy.roles.includes(pkg.role) && !owner.roles.includes(pkg.role)) problems.push({ code: "owner-role-mismatch", owner: pkg.owner });
    for (const dep of pkg.dependencies) {
      if (dep.owner === null) continue;
      const target = graph.find((pkg) => pkg.owner === dep.owner)!;
      localDependencies++;
      const forbidden = layer(pkg.owner) === "framework" && layer(target.owner) === "implementation" ? ["cargo-framework-no-implementation"] : [];
      for (const [name, rule] of rules) if ((rule.fromRoles.includes(pkg.role) || sourceOwners.get(name)!.some((pattern) => pattern.test(pkg.owner))) && (rule.toRoles.includes(target.role) || rule.toOwnerSegments?.some((segment: string) => target.owner.split("/").includes(segment)))) forbidden.push(name);
      for (const rule of forbidden) violations.push({ rule, from: pkg.owner, to: target.owner, alias: dep.alias, kind: dep.kind, optional: dep.optional, platform: dep.platform });
    }
  }
  violations.sort((a, b) => {
    const first = JSON.stringify([a.rule, a.from, a.to, a.alias, a.kind, a.platform]), second = JSON.stringify([b.rule, b.from, b.to, b.alias, b.kind, b.platform]);
    return first < second ? -1 : first > second ? 1 : 0;
  });
  return { packages: graph.length, localDependencies, violations, problems };
}

import { CargoMetadataCaptureBudget } from "./⏱️budget/🟦️.ts";
import { startNativeProgress } from "../../../../../../../../🔨️modules/🏃️process/🎛️owned-execution/🟦️.ts";
import { discoverCargoWorkspaces, prepareCargoWorkspaceInvocation } from "../../../../🗂️workspaces/🦀️cargo/🟦️.ts";
import { readFileSync } from "node:fs";
import { join } from "node:path";

import { cargoDirectionInventory, cargoDirectionMetadata, cargoDependencyDirectionReport, type CargoDirectionPolicy } from "../🟦️.ts";

/** 🦀️ Checks every authored Cargo declaration with independent manifest and metadata inventories. */
export async function verifyCargoDependencyDirection(repoRoot: string): Promise<void> {
  const taxonomy = JSON.parse(readFileSync(join(repoRoot, "🧰️framework/🛍️products/🦑️repo/🔨️modules/📚️library/🔣️taxonomy.json"), "utf8"));
  const policy: CargoDirectionPolicy = { areaLayers: taxonomy.areaLayers, ...taxonomy.cargoDependencyDirections };
  const inventory = cargoDirectionInventory(repoRoot);
  console.log(`[cargo-dependency-direction] resolving all declaration kinds; inventoriedPackages=${inventory.length}`);
  const metadata: unknown[] = [], budget = new CargoMetadataCaptureBudget(30_000);
  for (const scope of discoverCargoWorkspaces(repoRoot)) {
    const args = ["metadata", "--format-version", "1", "--no-deps", "--offline", "--locked", "--manifest-path", join(repoRoot, scope.manifest)];
    prepareCargoWorkspaceInvocation(repoRoot, args, repoRoot);
    const remaining = budget.remainingMs;
    if (remaining <= 0) throw new Error("Cargo metadata capture budget exhausted");
    const captureStarted = performance.now();
    const child = Bun.spawn(["cargo", ...args], { cwd: repoRoot, stdout: "pipe", stderr: "pipe" });
    let stopped = "";
    const stop = (reason: string): void => { stopped ||= reason; child.kill(); };
    const interrupt = (): void => stop("SIGINT"), terminate = (): void => stop("SIGTERM");
    process.once("SIGINT", interrupt); process.once("SIGTERM", terminate);
    const timeout = setTimeout(() => stop("timeout 30000ms"), remaining), progress = startNativeProgress(`cargo-dependency-direction:${scope.manifest}`);
    try {
      const result = await Promise.all([new Response(child.stdout).text(), new Response(child.stderr).text(), child.exited]);
      if (stopped || result[2] !== 0) throw new Error(stopped || result[1] || "Cargo direction metadata scan failed");
      metadata.push(JSON.parse(result[0]));
    } finally { clearTimeout(timeout); progress(); process.off("SIGINT", interrupt); process.off("SIGTERM", terminate); budget.charge(performance.now() - captureStarted); }
  }
  const report = cargoDependencyDirectionReport(cargoDirectionMetadata(metadata, repoRoot), inventory, policy);
  for (const problem of report.problems) console.error(`[cargo-dependency-direction] ${problem.code}: ${problem.owner}`);
  for (const edge of report.violations) console.error(`[cargo-dependency-direction] ${edge.rule}: ${edge.from} → ${edge.to}; alias=${edge.alias}; kind=${edge.kind}; optional=${edge.optional}; platform=${edge.platform ?? "all"}`);
  if (report.problems.length || report.violations.length) throw new Error(`Cargo dependency direction failed: ${report.violations.length} strict violations, ${report.problems.length} metadata problems, ${report.localDependencies} local declarations, ${report.packages} packages`);
  console.log(`[cargo-dependency-direction] passed; localDeclarations=${report.localDependencies}; packages=${report.packages}`);
}

